# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">SAĞLIK ALANINDA BİYOTEKNOLOJİ VE GEN TERAPİSİ (12.1.2.4)</text>\n  <rect x="20" y="45" width="210" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Tıbbi Protein ve İlaç Üretimi</text>\n  <rect x="32" y="80" width="186" height="46" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="125" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Rekombinant İnsülin</text>\n  <text x="125" y="114" text-anchor="middle" font-size="10" fill="#1e3a8a">Diyabet tedavisinde bakteriyel üretim</text>\n  <rect x="32" y="134" width="186" height="46" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="125" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">İnterferon ve Monoklonal Antikor</text>\n  <text x="125" y="168" text-anchor="middle" font-size="10" fill="#1e3a8a">Viral enfeksiyon ve kanser hedefleme</text>\n  <rect x="32" y="188" width="186" height="44" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="125" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Rekombinant Aşı ve Antibiyotik</text>\n  <text x="125" y="222" text-anchor="middle" font-size="10" fill="#1e3a8a">Saflaştırılmış antijenlerle bağışıklık</text>\n  <rect x="245" y="45" width="210" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Gen Terapisi ve Danışmanlık</text>\n  <text x="257" y="94" font-size="11" font-weight="bold" fill="#14532d">• Gen Terapisi Mekanizması:</text>\n  <text x="265" y="112" font-size="10.5" fill="#14532d">Hastalığa yol açan bozuk veya</text>\n  <text x="265" y="127" font-size="10.5" fill="#14532d">eksik genin yerine viral vektörler</text>\n  <text x="265" y="142" font-size="10.5" fill="#14532d">aracılığıyla sağlıklı gen aktarılır.</text>\n  <text x="257" y="168" font-size="11" font-weight="bold" fill="#14532d">• Genetik Danışmanlık:</text>\n  <text x="265" y="186" font-size="10.5" fill="#14532d">Kalıtsal hastalık taşıyıcılığı olan</text>\n  <text x="265" y="201" font-size="10.5" fill="#14532d">ailelere soyağacı ve prenatal tarama</text>\n  <text x="265" y="216" font-size="10.5" fill="#14532d">testleriyle risk analizi sunulur.</text>\n  <rect x="470" y="45" width="210" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Biyogüvenlik ve Biyoetik</text>\n  <text x="482" y="94" font-size="11" font-weight="bold" fill="#78350f">• GDO ve Ekolojik Etkiler:</text>\n  <text x="490" y="112" font-size="10.5" fill="#78350f">Polenlerle yabani türlere gen</text>\n  <text x="490" y="127" font-size="10.5" fill="#78350f">kaçışı, alerjik reaksiyon riski ve</text>\n  <text x="490" y="142" font-size="10.5" fill="#78350f">yerel tohum çeşitliliğinin azalması.</text>\n  <text x="482" y="168" font-size="11" font-weight="bold" fill="#78350f">• Biyoetik İlkeler:</text>\n  <text x="490" y="186" font-size="10.5" fill="#78350f">İnsan klonlama yasağı, genetik</text>\n  <text x="490" y="201" font-size="10.5" fill="#78350f">verilerin gizliliği ve Cartagena</text>\n  <text x="490" y="216" font-size="10.5" fill="#78350f">Biyogüvenlik Protokolü denetimi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="24" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">FOTOSENTEZ HIZINI ETKİLEYEN ÇEVRESEL FAKTÖRLER (12.2.2)</text>\n  <rect x="20" y="42" width="210" height="202" rx="8" fill="#ffffff" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="125" y="62" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. Işık Şiddeti ve CO₂ Miktarı</text>\n  <line x1="45" y1="190" x2="205" y2="190" stroke="#334155" stroke-width="2"/>\n  <line x1="45" y1="190" x2="45" y2="75" stroke="#334155" stroke-width="2"/>\n  <path d="M 60 190 Q 95 110 130 110 L 195 110" fill="none" stroke="#2563eb" stroke-width="2.5"/>\n  <text x="125" y="210" text-anchor="middle" font-size="10" fill="#334155">CO₂ Derişimi / Işık Şiddeti</text>\n  <text x="125" y="228" text-anchor="middle" font-size="9.5" fill="#1e3a8a">Belirli eşikten sonra hız sabitlenir</text>\n  <rect x="245" y="42" width="210" height="202" rx="8" fill="#ffffff" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="350" y="62" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#dc2626">2. Sıcaklık (Enzim Etkisi)</text>\n  <line x1="270" y1="190" x2="430" y2="190" stroke="#334155" stroke-width="2"/>\n  <line x1="270" y1="190" x2="270" y2="75" stroke="#334155" stroke-width="2"/>\n  <path d="M 275 180 Q 350 65 415 190" fill="none" stroke="#dc2626" stroke-width="2.5"/>\n  <line x1="348" y1="122" x2="348" y2="190" stroke="#94a3b8" stroke-dasharray="3,3"/>\n  <text x="348" y="205" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b91c1c">25-35 °C (Optimum)</text>\n  <text x="350" y="228" text-anchor="middle" font-size="9.5" fill="#991b1b">Yüksek ısıda enzimler denatüre olur</text>\n  <rect x="470" y="42" width="210" height="202" rx="8" fill="#ffffff" stroke="#cbd5e1" stroke-width="1.5"/>\n  <text x="575" y="62" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#16a34a">3. Işığın Dalga Boyu (Engelmann)</text>\n  <line x1="495" y1="190" x2="655" y2="190" stroke="#334155" stroke-width="2"/>\n  <line x1="495" y1="190" x2="495" y2="75" stroke="#334155" stroke-width="2"/>\n  <path d="M 505 95 Q 540 120 575 170 Q 610 125 645 100" fill="none" stroke="#16a34a" stroke-width="2.5"/>\n  <text x="515" y="205" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#6b21a8">Mor-Mavi</text>\n  <text x="575" y="205" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#15803d">Yeşil</text>\n  <text x="638" y="205" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#dc2626">Kırmızı</text>\n  <text x="575" y="228" text-anchor="middle" font-size="9.5" fill="#166534">Yeşil yansıtılır; mor ve kırmızıda yüksek</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">FOTOSENTEZ HIZINI ETKİLEYEN GENETİK FAKTÖRLER VE MİNERALLER</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Genetik (Kalıtsal) Faktörler</text>\n  <text x="40" y="95" font-size="11" fill="#14532d">• <tspan font-weight="bold">Kloroplast ve Klorofil Sayısı:</tspan> Artışı</text>\n  <text x="52" y="111" font-size="10.5" fill="#14532d">soğurulan ışık miktarını ve hızı artırır.</text>\n  <text x="40" y="134" font-size="11" fill="#14532d">• <tspan font-weight="bold">Yaprak Yüzey Genişliği ve Sayısı:</tspan></text>\n  <text x="52" y="150" font-size="10.5" fill="#14532d">Işık yakalama kapasitesini doğrudan yükseltir.</text>\n  <text x="40" y="173" font-size="11" fill="#14532d">• <tspan font-weight="bold">Stoma Sayısı, Konumu ve Büyüklüğü:</tspan></text>\n  <text x="52" y="189" font-size="10.5" fill="#14532d">Gaz alışverişi (CO₂ girişi) hızını belirler.</text>\n  <text x="40" y="212" font-size="11" fill="#14532d">• <tspan font-weight="bold">Kütikula Kalınlığı:</tspan> Kalınlaştıkça ışığı</text>\n  <text x="52" y="228" font-size="10.5" fill="#14532d">geçirme oranı ve fotosentez hızı azalır.</text>\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Minimum Yasası ve Su/pH Etkisi</text>\n  <text x="380" y="95" font-size="11" fill="#78350f">• <tspan font-weight="bold">Minimum Kuralı (Liebig):</tspan> Fotosentez</text>\n  <text x="392" y="111" font-size="10.5" fill="#78350f">hızını toprakta oransal olarak en az</text>\n  <text x="392" y="127" font-size="10.5" fill="#78350f">bulunan mineral (Fe, Mg, N, P, K) sınırlar.</text>\n  <text x="380" y="152" font-size="11" fill="#78350f">• <tspan font-weight="bold">Su Oranı (%15 Eşiği):</tspan> Hücredeki su</text>\n  <text x="392" y="168" font-size="10.5" fill="#78350f">oranı %15\'in altına düşerse enzimler</text>\n  <text x="392" y="184" font-size="10.5" fill="#78350f">çalışamaz ve stomalar kapanır.</text>\n  <text x="380" y="209" font-size="11" fill="#78350f">• <tspan font-weight="bold">Ortam pH Değeri:</tspan> Stroma enzimleri</text>\n  <text x="392" y="225" font-size="10.5" fill="#78350f">kendilerine özgü optimum pH\'ta çalışır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
